/* Portfolio adapter: defer only real poster image sources, never player media. */
;(function () {
  'use strict';
  const selector = 'img[data-poster-fallback]';
  const deferredSelector = 'img.deferred-poster[data-src]';
  let loader = null;

  function isRealSource(image) {
    const source = image.currentSrc || image.getAttribute('src') || '';
    return source !== '' && !source.startsWith('data:');
  }

  function applyLoadedPoster(image) {
    if (!image.naturalWidth || !isRealSource(image)) return;
    const surface = image.closest('.primary-poster, .video-poster, .scene-card');
    if (surface) surface.style.setProperty('--poster', 'url(' + JSON.stringify(image.currentSrc || image.src) + ')');
    image.classList.remove('loading', 'error');
    image.classList.add('loaded');
    if (image.hasAttribute('data-src')) image.setAttribute('data-ll-status', 'loaded');
  }

  function useFallback(image) {
    const fallback = image.dataset.posterFallback;
    if (!fallback || image.dataset.posterFallbackUsed === 'true') return;
    image.dataset.posterFallbackUsed = 'true';
    if (image.hasAttribute('data-src')) image.dataset.src = fallback;
    image.src = fallback;
  }

  function loadWithoutObserver(image) {
    if (image.dataset.src && !isRealSource(image)) image.src = image.dataset.src;
  }

  function updatePosters() {
    document.querySelectorAll(selector).forEach(image => {
      if (!image.complete || !isRealSource(image)) return;
      if (image.naturalWidth) applyLoadedPoster(image);
      else useFallback(image);
    });
    if (loader) {
      try { loader.update(); }
      catch {
        try { loader.destroy(); } catch { /* Eager fallback still works without the library. */ }
        loader = null;
      }
    }
    if (!loader) document.querySelectorAll(deferredSelector).forEach(loadWithoutObserver);
  }

  // Capture also covers cached images and JPG fallbacks independently of library status.
  document.addEventListener('load', event => {
    const image = event.target;
    if (image instanceof HTMLImageElement && image.matches(selector)) applyLoadedPoster(image);
  }, true);
  document.addEventListener('error', event => {
    const image = event.target;
    if (image instanceof HTMLImageElement && image.matches(selector) && isRealSource(image)) useFallback(image);
  }, true);

  if (typeof window.IntersectionObserver === 'function' && typeof window.LazyLoad === 'function') {
    try {
      loader = new window.LazyLoad({
        elements_selector: deferredSelector,
        threshold: 120,
        use_native: false,
        unobserve_entered: true,
        unobserve_completed: true,
        cancel_on_exit: false,
        callback_loaded: applyLoadedPoster,
        callback_error: useFallback
      });
    } catch {
      loader = null;
    }
  }

  document.addEventListener('portfolio:projectrender', updatePosters);
  document.addEventListener('click', event => {
    const button = event.target.closest('[data-play]');
    const image = button?.querySelector(deferredSelector);
    if (!image || isRealSource(image)) return;
    // A click can arrive before the observer callback. It never waits for the poster.
    if (loader) loader.loadAll([image]);
    else loadWithoutObserver(image);
  }, true);
  updatePosters();
})();

